insert into batch.batch_day_replay_preview_token (
    tenant_id, token_hash, request_hash, snapshot_hash, expires_at
) values (
    #{tenantId}, #{tokenHash}, #{requestHash}, #{snapshotHash}, #{expiresAt}
)

mapper.update:
update batch.batch_day_replay_preview_token
set consumed_at = clock_timestamp()
where tenant_id = #{tenantId}
  and token_hash = #{tokenHash}
  and consumed_at is null
  and expires_at > clock_timestamp()

update batch.batch_day_replay_preview_token
set session_id = #{sessionId}
where tenant_id = #{tenantId}
  and token_hash = #{tokenHash}
  and consumed_at is not null
  and session_id is null
